(function() {
    'use strict';

    class BankAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Full-Institution Bank';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    baseRate: 7.0,
                    retailDefaultMult: 1.0,
                    corpDefaultMult: 1.0,
                    depSensitivity: 1.0,
                    icon: '🏦',
                    description_en: 'Year 1 — Stable economy. GDP growth at 3.5%, inflation at 4%. BancoMontaverde competes against BancoPlex (market leader, 12.5% Tier 1) and Scotiabank Montaverde (aggressive expansion). Your mandate: grow shareholder value while maintaining capital discipline. Retail Banking has a 72% cost-to-income ratio — significant room for efficiency gains through technology investment. Corporate Banking delivers strong returns but depends on wholesale funding for the loan-deposit gap.',
                    description_es: 'Anio 1 — Economia estable. Crecimiento del PIB al 3.5%, inflacion al 4%. BancoMontaverde compite contra BancoPlex (lider de mercado, 12.5% Tier 1) y Scotiabank Montaverde (expansion agresiva). Su mandato: hacer crecer el valor para los accionistas manteniendo disciplina de capital. Banca Minorista tiene un ratio de eficiencia del 72% — amplio margen para mejoras mediante inversion tecnologica. Banca Corporativa genera retornos solidos pero depende del fondeo mayorista.'
                },
                {
                    baseRate: 9.5,
                    retailDefaultMult: 2.5,
                    corpDefaultMult: 4.0,
                    depSensitivity: 2.5,
                    icon: '⚠️',
                    description_en: 'Year 2 — MACRO SHOCK. The Central Bank raises rates +250 bps to combat inflation. GDP growth slows to 0.5%, unemployment rises sharply. Corporate defaults spike — stressed sectors (construction, retail, tourism) show 8-12% default rates. Retail depositors demand higher rates or move funds to competitors. Wholesale funding costs surge. BancoGabriel (weak competitor, 10.5% Tier 1) is rumored to be under regulatory intervention. Your decisions now will determine whether BancoMontaverde emerges stronger or faces capital adequacy problems.',
                    description_es: 'Anio 2 — SHOCK MACROECONOMICO. El Banco Central sube tasas +250 pbs para combatir la inflacion. El PIB cae a 0.5%, el desempleo sube. Los impagos corporativos se disparan — sectores estresados muestran tasas del 8-12%. Los depositantes minoristas exigen mayores tasas o mueven fondos a competidores. Los costos de fondeo mayorista se disparan. BancoGabriel (competidor debil) esta bajo rumor de intervencion regulatoria. Sus decisiones ahora determinaran si BancoMontaverde emerge fortalecido o enfrenta problemas de suficiencia de capital.'
                },
                {
                    baseRate: 8.5,
                    retailDefaultMult: 1.5,
                    corpDefaultMult: 2.0,
                    depSensitivity: 1.5,
                    icon: '📈',
                    description_en: 'Year 3 — Partial Recovery. Rates ease -100 bps, but economic scars remain. A fintech competitor (FronteraTech) raises $500M and launches digital corporate lending with 30% faster approval and 50 bps lower spreads. Banco Fronterizo is acquired by a regional player. The market rewards banks that maintained capital discipline during the crisis. This is the final year — your CBVI (Comprehensive Bank Value Index) determines the winner.',
                    description_es: 'Anio 3 — Recuperacion parcial. Las tasas bajan -100 pbs pero las cicatrices economicas persisten. Un competidor fintech (FronteraTech) recauda $500M y lanza prestamos corporativos digitales con aprobacion 30% mas rapida y spreads 50 pbs menores. Banco Fronterizo es adquirido por un jugador regional. El mercado premia a los bancos que mantuvieron disciplina de capital durante la crisis. Este es el anio final — su CBVI (Indice de Valor Bancario Integral) determina al ganador.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    equity: 7000,
                    retailDep: 18000,
                    retailLoans: 12000,
                    corpDep: 8000,
                    corpLoans: 11000,
                    cumTechInvest: 0,
                    shares: 824,
                    tier1Ratio: 0.112,
                    roe: 0.132,
                    tbvps: 8.50,
                    cir: 0.56,
                    netIncome: 905,
                    pb: 1.05,
                    retailNI: 249,
                    corpNI: 706,
                    retailCIR: 0.72,
                    corpCIR: 0.34,
                    niHistory: [],
                    roeHistory: [],
                    tier1History: [],
                    tbvpsHistory: [],
                    retailNIHistory: [],
                    corpNIHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    retailDepRate: 2.0,
                    retailLoanRate: 9.0,
                    corpSpread: 300,
                    capitalRetailPct: 45,
                    techInvest: 50,
                    dividendPayout: 40
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var el;
            el = document.getElementById('retailDepRateInput');
            if (el) decisions.retailDepRate = parseFloat(el.value);
            el = document.getElementById('retailLoanRateInput');
            if (el) decisions.retailLoanRate = parseFloat(el.value);
            el = document.getElementById('corpSpreadInput');
            if (el) decisions.corpSpread = parseFloat(el.value);
            el = document.getElementById('capitalRetailInput');
            if (el) decisions.capitalRetailPct = parseFloat(el.value);
            el = document.getElementById('techInvestInput');
            if (el) decisions.techInvest = parseFloat(el.value);
            el = document.getElementById('dividendInput');
            if (el) decisions.dividendPayout = parseFloat(el.value);

            if (isNaN(decisions.retailDepRate) || decisions.retailDepRate < 0.5 || decisions.retailDepRate > 6.0) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_dep_rate'), 'warning');
                return false;
            }
            if (isNaN(decisions.retailLoanRate) || decisions.retailLoanRate < 5.0 || decisions.retailLoanRate > 18.0) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_loan_rate'), 'warning');
                return false;
            }
            if (isNaN(decisions.corpSpread) || decisions.corpSpread < 100 || decisions.corpSpread > 600) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_spread'), 'warning');
                return false;
            }
            if (isNaN(decisions.capitalRetailPct) || decisions.capitalRetailPct < 25 || decisions.capitalRetailPct > 75) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_capital'), 'warning');
                return false;
            }
            if (isNaN(decisions.techInvest) || decisions.techInvest < 0 || decisions.techInvest > 200) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_tech'), 'warning');
                return false;
            }
            if (isNaN(decisions.dividendPayout) || decisions.dividendPayout < 0 || decisions.dividendPayout > 80) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_dividend'), 'warning');
                return false;
            }


            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var rp = this.ROUNDS[roundIdx];
            var baseRate = rp.baseRate;

            var clamp = function(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); };

            /* --- Retail Banking --- */
            var depGrowth = 0.03 + (d.retailDepRate - baseRate * 0.3) * 0.015 * rp.depSensitivity;
            depGrowth = clamp(depGrowth, -0.06, 0.08);
            ds.retailDep = Math.round(ds.retailDep * (1 + depGrowth));

            var retailLoanGrowthRaw = 0.04 - (d.retailLoanRate - 9.0) * 0.008;
            var retailLoanGrowthCap = (d.capitalRetailPct / 45) * 0.06;
            var retailLoanGrowth = clamp(Math.min(retailLoanGrowthRaw, retailLoanGrowthCap), -0.05, 0.08);
            ds.retailLoans = Math.round(ds.retailLoans * (1 + retailLoanGrowth));

            var excessRetailDep = Math.max(0, ds.retailDep - ds.retailLoans);
            var retailNII = ds.retailLoans * d.retailLoanRate / 100
                + excessRetailDep * baseRate / 100 * 0.4
                - ds.retailDep * d.retailDepRate / 100 * 0.3;

            var retailFees = ds.retailDep * 0.017;
            var retailRevenue = retailNII + retailFees;

            ds.cumTechInvest += d.techInvest;
            var techEffect = Math.min(ds.cumTechInvest / 500, 0.25);
            var retailBaseOpex = 1050;
            var depScale = 1 + (ds.retailDep / 18000 - 1) * 0.3;
            var retailOpex = retailBaseOpex * (1 - techEffect) * depScale;

            var retailLosses = ds.retailLoans * 0.0125 * rp.retailDefaultMult;
            var retailNI = retailNII + retailFees - retailOpex - retailLosses;
            var retailCIR = retailRevenue > 0 ? retailOpex / retailRevenue : 1;

            /* --- Corporate Banking --- */
            var corpDepGrowth = 0.02;
            ds.corpDep = Math.round(ds.corpDep * (1 + corpDepGrowth));

            var corpLoanGrowthRaw = 0.03 - (d.corpSpread - 300) * 0.00003;
            var corpLoanGrowthCap = ((100 - d.capitalRetailPct) / 55) * 0.05;
            var corpLoanGrowth = clamp(Math.min(corpLoanGrowthRaw, corpLoanGrowthCap), -0.04, 0.06);
            ds.corpLoans = Math.round(ds.corpLoans * (1 + corpLoanGrowth));

            var corpLoanRate = (baseRate + d.corpSpread / 100) / 100;
            var fundingGap = Math.max(0, ds.corpLoans - ds.corpDep);
            var corpDepCost = ds.corpDep * baseRate / 100 * 0.3;
            var wholesaleCost = fundingGap * (baseRate + 1.5) / 100;
            var corpNII = ds.corpLoans * corpLoanRate - corpDepCost - wholesaleCost;

            var corpFees = ds.corpLoans * 0.05;
            var corpRevenue = corpNII + corpFees;

            var corpOpex = 400 * (ds.corpLoans / 11000);
            var corpLosses = ds.corpLoans * 0.011 * rp.corpDefaultMult;
            var corpNI = corpNII + corpFees - corpOpex - corpLosses;
            var corpCIR = corpRevenue > 0 ? corpOpex / corpRevenue : 1;

            /* --- Enterprise --- */
            var totalNI = retailNI + corpNI - d.techInvest;
            var dividends = totalNI > 0 ? totalNI * d.dividendPayout / 100 : 0;
            var retained = totalNI - dividends;
            ds.equity += retained;

            var totalRevenue = retailRevenue + corpRevenue;
            var totalOpex = retailOpex + corpOpex + d.techInvest;
            var totalLosses = retailLosses + corpLosses;
            var totalLoans = ds.retailLoans + ds.corpLoans;

            var rwa = ds.retailLoans * 0.75 + ds.corpLoans * 1.5 + 24500;
            var tier1Capital = ds.equity * 0.8;
            var tier1Ratio = rwa > 0 ? tier1Capital / rwa : 0;
            var roe = ds.equity > 0 ? totalNI / ds.equity : 0;
            var tbvps = ds.equity / ds.shares;
            var cir = totalRevenue > 0 ? totalOpex / totalRevenue : 1;
            var loanLossRatio = totalLoans > 0 ? totalLosses / totalLoans : 0;

            /* Price-to-Book */
            var pb = 0.6;
            if (roe > 0.12) pb += (roe - 0.12) * 5;
            if (roe < 0.08) pb -= (0.08 - roe) * 3;
            if (tier1Ratio > 0.11) pb += 0.08;
            if (tier1Ratio < 0.10) pb -= 0.25;
            if (cir < 0.55) pb += 0.06;
            pb = Math.max(0.3, Math.min(2.0, pb));

            /* Store for display */
            ds.tier1Ratio = tier1Ratio;
            ds.roe = roe;
            ds.tbvps = tbvps;
            ds.cir = cir;
            ds.netIncome = Math.round(totalNI);
            ds.pb = Math.round(pb * 100) / 100;
            ds.retailNI = Math.round(retailNI);
            ds.corpNI = Math.round(corpNI);
            ds.retailCIR = retailCIR;
            ds.corpCIR = corpCIR;

            /* History arrays for charts */
            ds.niHistory.push(Math.round(totalNI));
            ds.roeHistory.push(Math.round(roe * 1000) / 10);
            ds.tier1History.push(Math.round(tier1Ratio * 1000) / 10);
            ds.tbvpsHistory.push(Math.round(tbvps * 100) / 100);
            ds.retailNIHistory.push(Math.round(retailNI));
            ds.corpNIHistory.push(Math.round(corpNI));

            var period = state.currentPeriod;
            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                baseRate: baseRate,
                retailDepRate: d.retailDepRate,
                retailLoanRate: d.retailLoanRate,
                corpSpread: d.corpSpread,
                capitalRetailPct: d.capitalRetailPct,
                techInvest: d.techInvest,
                dividendPayout: d.dividendPayout,
                retailNII: Math.round(retailNII),
                retailFees: Math.round(retailFees),
                retailOpex: Math.round(retailOpex),
                retailLosses: Math.round(retailLosses),
                retailNI: Math.round(retailNI),
                corpNII: Math.round(corpNII),
                corpFees: Math.round(corpFees),
                corpOpex: Math.round(corpOpex),
                corpLosses: Math.round(corpLosses),
                corpNI: Math.round(corpNI),
                totalNI: Math.round(totalNI),
                dividends: Math.round(dividends),
                equity: Math.round(ds.equity),
                tier1Ratio: Math.round(tier1Ratio * 1000) / 10,
                roe: Math.round(roe * 1000) / 10,
                tbvps: Math.round(tbvps * 100) / 100,
                cir: Math.round(cir * 1000) / 10,
                loanLossRatio: Math.round(loanLossRatio * 10000) / 100,
                pb: Math.round(pb * 100) / 100
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('tier1Display', 'domainState.tier1Ratio', function(v) { return (v * 100).toFixed(1) + '%'; });
            uiManager.bind('roeDisplay', 'domainState.roe', function(v) { return (v * 100).toFixed(1) + '%'; });
            uiManager.bind('tbvpsDisplay', 'domainState.tbvps', function(v) { return '$' + v.toFixed(2); });
            uiManager.bind('cirDisplay', 'domainState.cir', function(v) { return (v * 100).toFixed(0) + '%'; });
            uiManager.bind('niDisplay', 'domainState.netIncome', function(v) { return '$' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('pbDisplay', 'domainState.pb', function(v) { return v.toFixed(2) + 'x'; });
            uiManager.bind('retailDepDisplay', 'domainState.retailDep', function(v) { return '$' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('retailLoansDisplay', 'domainState.retailLoans', function(v) { return '$' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('retailNIDisplay', 'domainState.retailNI', function(v) { return '$' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('retailCIRDisplay', 'domainState.retailCIR', function(v) { return (v * 100).toFixed(0) + '%'; });
            uiManager.bind('corpDepDisplay', 'domainState.corpDep', function(v) { return '$' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('corpLoansDisplay', 'domainState.corpLoans', function(v) { return '$' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('corpNIDisplay', 'domainState.corpNI', function(v) { return '$' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('corpCIRDisplay', 'domainState.corpCIR', function(v) { return (v * 100).toFixed(0) + '%'; });
        }

        getChartConfig() {
            return {
                plChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Retail NI ($M)',
                                data: [],
                                backgroundColor: 'rgba(30,136,229,0.7)',
                                borderColor: '#1e88e5',
                                borderWidth: 2
                            },
                            {
                                label: 'Corporate NI ($M)',
                                data: [],
                                backgroundColor: 'rgba(67,160,71,0.7)',
                                borderColor: '#43a047',
                                borderWidth: 2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Net Income by Business Unit' } },
                        scales: { y: { beginAtZero: true, title: { display: true, text: '$M' } } }
                    }
                },
                capitalChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Tier 1 Ratio (%)',
                                data: [],
                                borderColor: '#2e7d32',
                                backgroundColor: 'rgba(46,125,50,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: 'ROE (%)',
                                data: [],
                                borderColor: '#1565c0',
                                backgroundColor: 'rgba(21,101,192,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: 'TBVPS ($)',
                                data: [],
                                borderColor: '#6a1b9a',
                                backgroundColor: 'rgba(106,27,154,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Capital & Performance Metrics' } },
                        scales: {
                            y: {
                                type: 'linear',
                                position: 'left',
                                beginAtZero: true,
                                title: { display: true, text: '%' }
                            },
                            y1: {
                                type: 'linear',
                                position: 'right',
                                beginAtZero: false,
                                title: { display: true, text: '$ per share' },
                                grid: { drawOnChartArea: false }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = state.domainState;
            var labels = ds.niHistory.map(function(_, i) { return 'Y' + (i + 1); });
            return {
                plChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.retailNIHistory },
                        { data: ds.corpNIHistory }
                    ]
                },
                capitalChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.tier1History },
                        { data: ds.roeHistory },
                        { data: ds.tbvpsHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var finalState = history[history.length - 1];
            var results = finalState.results || {};
            var totalNIs = history.map(function(h) { return (h.results && h.results.totalNI) || 0; });
            var avgNI = totalNIs.reduce(function(s, v) { return s + v; }, 0) / totalNIs.length;

            /* CBVI Calculation */
            var startTBVPS = 8.50;
            var endTBVPS = results.tbvps || startTBVPS;
            var tbvpsGrowth = (endTBVPS - startTBVPS) / startTBVPS;
            var roe = (results.roe || 0) / 100;
            var tier1 = (results.tier1Ratio || 0) / 100;
            var cir = (results.cir || 0) / 100;
            var lossRatio = (results.loanLossRatio || 0) / 100;
            var pb = results.pb || 0.5;

            var cbvi = 0;
            cbvi += Math.min(tbvpsGrowth / 0.36, 1) * 25;
            cbvi += Math.min(roe / 0.15, 1) * 20;
            if (tier1 >= 0.10 && tier1 <= 0.14) cbvi += 15;
            else if (tier1 > 0.14) cbvi += 10;
            else cbvi += 0;
            cbvi += Math.max(0, (0.07 - Math.abs(roe * 0.04 - cir * 0.01))) * 15 / 0.07;
            cbvi += Math.max(0, 1 - cir / 0.70) * 12;
            cbvi += Math.max(0, 1 - lossRatio / 0.04) * 8;
            cbvi += Math.min(pb / 1.5, 1) * 5;

            /* Penalties */
            if (tier1 < 0.10) cbvi -= 10;
            if (tier1 > 0.14) cbvi -= 5;
            if (roe < 0.08) cbvi -= 15;

            cbvi = Math.max(0, Math.min(100, Math.round(cbvi)));

            var performance = 'Needs Improvement';
            if (cbvi >= 75) performance = 'Excellent — Top-Tier Bank CEO';
            else if (cbvi >= 60) performance = 'Good — Solid Banking Leadership';
            else if (cbvi >= 45) performance = 'Adequate — Room for Strategic Improvement';

            var insights = [];
            if (roe > 0.12) insights.push('Strong ROE indicates effective capital deployment and pricing strategy.');
            if (roe <= 0.08) insights.push('ROE below cost of equity — the bank is destroying shareholder value.');
            if (tier1 < 0.10) insights.push('Capital ratio below regulatory minimum — the bank faces supervisory action.');
            if (tier1 > 0.14) insights.push('Over-capitalization may indicate missed growth opportunities or excess conservatism.');
            if (cir < 0.55) insights.push('Excellent cost efficiency — technology investment is paying off.');
            if (cir > 0.65) insights.push('High cost-to-income ratio — retail transformation should be a priority.');
            if (lossRatio > 0.03) insights.push('Elevated loan losses — credit risk management needs attention.');
            if (pb > 1.2) insights.push('Price-to-book premium reflects market confidence in management quality.');
            if (pb < 0.8) insights.push('Trading below book value — the market doubts future profitability.');

            return {
                cbvi: cbvi,
                performance: performance,
                tbvpsGrowth: Math.round(tbvpsGrowth * 1000) / 10,
                finalROE: results.roe,
                finalTier1: results.tier1Ratio,
                finalCIR: results.cir,
                finalPB: results.pb,
                avgNetIncome: Math.round(avgNI),
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.tier1Ratio < 10.0) return window.mySimulation.t('hint_capital_low');
            if (results.roe < 8.0) return window.mySimulation.t('hint_roe_low');
            if (results.loanLossRatio > 3.0) return window.mySimulation.t('hint_losses_high');
            if (results.cir > 60) return window.mySimulation.t('hint_cir_high');
            if (results.roe > 14.0 && results.tier1Ratio > 11.0) return window.mySimulation.t('hint_strong');
            return null;
        }

