        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            var panel = document.getElementById('briefingPanel');
            var iconEl = document.getElementById('briefingIcon');
            var rateEl = document.getElementById('baseRateDisplay');

            var lang = 'en';
            try { lang = window.mySimulation && window.mySimulation.language ? window.mySimulation.language : 'en'; } catch(e) {}
            var desc = lang === 'es' ? round.description_es : round.description_en;

            if (briefEl) briefEl.innerHTML = desc;
            if (iconEl) iconEl.textContent = round.icon;
            if (rateEl) rateEl.textContent = round.baseRate.toFixed(1) + '%';

            if (panel) {
                if (idx === 1) {
                    panel.classList.add('bank072-shock');
                } else {
                    panel.classList.remove('bank072-shock');
                }
            }
        }
